import { useEffect, useId, useRef, useState } from 'react';
import { ChevronDown, type LucideIcon } from 'lucide-react';

export interface ChatHeaderMenuItem {
  id: string;
  label: string;
  icon: LucideIcon;
  onSelect: () => void | Promise<void>;
  danger?: boolean;
}

interface ChatHeaderMenuProps {
  label: string;
  icon: LucideIcon;
  items: ChatHeaderMenuItem[];
  showLabel?: boolean;
}

export function ChatHeaderMenu({
  label,
  icon: TriggerIcon,
  items,
  showLabel = true,
}: ChatHeaderMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const menuId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!isOpen) return;

    const handlePointerDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setIsOpen(false);
        triggerRef.current?.focus();
      }
    };

    document.addEventListener('pointerdown', handlePointerDown);
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('pointerdown', handlePointerDown);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen]);

  const handleSelect = (item: ChatHeaderMenuItem) => {
    setIsOpen(false);
    void item.onSelect();
  };

  return (
    <div ref={rootRef} className="relative">
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={isOpen}
        aria-controls={isOpen ? menuId : undefined}
        aria-label={label}
        onClick={() => setIsOpen((current) => !current)}
        className={`chat-header-menu-trigger flex h-10 items-center justify-center gap-2 rounded-full border px-3 transition active:scale-[0.97] ${
          isOpen ? 'is-open' : ''
        } ${showLabel ? '' : 'w-10 px-0'}`}
      >
        <TriggerIcon className="h-[18px] w-[18px]" aria-hidden="true" />
        {showLabel && <span className="chat-header-menu-label text-xs font-bold">{label}</span>}
        {showLabel && (
          <ChevronDown
            className={`chat-header-menu-label h-3.5 w-3.5 transition-transform ${isOpen ? 'rotate-180' : ''}`}
            aria-hidden="true"
          />
        )}
      </button>

      {isOpen && (
        <div
          id={menuId}
          role="menu"
          aria-label={label}
          className="chat-header-dropdown absolute right-0 top-[calc(100%+10px)] z-50 w-60 overflow-hidden rounded-[20px] border p-1.5 shadow-2xl backdrop-blur-2xl"
        >
          {items.map((item) => {
            const ItemIcon = item.icon;

            return (
              <button
                type="button"
                role="menuitem"
                key={item.id}
                onClick={() => handleSelect(item)}
                className={`chat-header-dropdown-item flex w-full items-center gap-3 rounded-[14px] px-3 py-2.5 text-left text-sm font-semibold transition ${
                  item.danger ? 'is-danger' : ''
                }`}
              >
                <span className="chat-header-dropdown-icon flex h-8 w-8 shrink-0 items-center justify-center rounded-[11px]">
                  <ItemIcon className="h-4 w-4" aria-hidden="true" />
                </span>
                <span className="truncate">{item.label}</span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}
