import React, { startTransition, useCallback, useEffect, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  X, Store, Users, Sparkles,
  Briefcase, ShoppingBag, Wrench, Download, Gamepad2,
  Monitor, Link, Megaphone, Box, Repeat, Zap, Receipt, Layers
} from 'lucide-react';
import { useListingWizard } from '../../context/ListingWizardContext';
import { SellerAccountSetup, useSellerDeclaration } from '../SellerAccountSetup';
import {
  dropdownPanelMotion,
  resetLiquidGlassPointer,
  trackLiquidGlassPointer,
} from '../ui/LiquidGlass';

interface WorkspaceCreateDropdownProps {
  isOpen: boolean;
  onClose: () => void;
  setActiveView: (view: string) => void;
  isAgentMode: boolean;
  setIsAgentMode: (val: boolean) => void;
  onOpenAi: () => void;
}

export const WorkspaceCreateDropdown: React.FC<WorkspaceCreateDropdownProps> = ({ 
  isOpen, onClose, setActiveView, isAgentMode, setIsAgentMode, onOpenAi 
}) => {
  const { openWizard } = useListingWizard();
  const { user, loading: declarationLoading, declared, markDeclared } = useSellerDeclaration(isOpen);
  const [isVisible, setIsVisible] = useState(isOpen);
  const [activeCategory, setActiveCategory] = useState<'sell' | 'money' | 'grow'>('sell');
  const closeTimerRef = useRef<number | null>(null);

  useEffect(() => {
    if (isOpen) {
      if (closeTimerRef.current !== null) {
        window.clearTimeout(closeTimerRef.current);
        closeTimerRef.current = null;
      }
      setIsVisible(true);
    } else {
      setIsVisible(false);
    }
  }, [isOpen]);

  useEffect(() => () => {
    if (closeTimerRef.current !== null) window.clearTimeout(closeTimerRef.current);
  }, []);

  const requestClose = useCallback(() => {
    // Paint the lightweight local exit state first. Updating the parent
    // WorkspaceLayout immediately causes a broad workspace render.
    setIsVisible(false);
    if (closeTimerRef.current !== null) window.clearTimeout(closeTimerRef.current);
    closeTimerRef.current = window.setTimeout(() => {
      closeTimerRef.current = null;
      startTransition(onClose);
    }, 180);
  }, [onClose]);

  const options = [
    {
      id: 'subscription',
      category: 'money',
      title: 'Subscription',
      description: 'Create a recurring payment plan',
      icon: Repeat,
      color: 'text-purple-400',
      bg: 'bg-purple-500/10',
      action: () => { setActiveView('money-subscriptions'); requestClose(); }
    },
    {
      id: 'quick-pay',
      category: 'money',
      title: 'Quick Pay',
      description: 'Generate a one-time payment link',
      icon: Zap,
      color: 'text-yellow-400',
      bg: 'bg-yellow-500/10',
      action: () => { setActiveView('money-links'); requestClose(); }
    },
    {
      id: 'invoice',
      category: 'money',
      title: 'Invoice',
      description: 'Send a professional invoice',
      icon: Receipt,
      color: 'text-emerald-400',
      bg: 'bg-emerald-500/10',
      action: () => { 
        setActiveView('money-invoices'); 
        requestClose(); 
        // Small delay to allow view to switch before opening wizard
        setTimeout(() => {
          window.dispatchEvent(new CustomEvent('open-invoice-wizard'));
        }, 100);
      }
    },
    {
      id: 'startup',
      category: 'grow',
      title: 'Startup',
      description: 'Launch a new startup venture',
      icon: Sparkles,
      color: 'text-yellow-400',
      bg: 'bg-yellow-500/10',
      action: () => { setActiveView('create-business'); requestClose(); }
    },
    {
      id: 'business',
      category: 'grow',
      title: 'Business',
      description: 'Register a new business entity',
      icon: Store,
      color: 'text-emerald-400',
      bg: 'bg-emerald-500/10',
      action: () => { setActiveView('create-business'); requestClose(); }
    },
    {
      id: 'job',
      category: 'grow',
      title: 'Job / Vacancy',
      description: 'Hire employees or post ads',
      icon: Briefcase,
      color: 'text-blue-400',
      bg: 'bg-blue-500/10',
      action: () => { openWizard('job'); requestClose(); }
    },
    {
      id: 'physical',
      category: 'sell',
      title: 'Physical Product',
      description: 'Sell tangible items like electronics or furniture',
      icon: ShoppingBag,
      color: 'text-emerald-400',
      bg: 'bg-emerald-500/10',
      action: () => { openWizard('product'); requestClose(); }
    },
    {
      id: 'service',
      category: 'sell',
      title: 'Service',
      description: 'Offer services like web design or consulting',
      icon: Wrench,
      color: 'text-indigo-400',
      bg: 'bg-indigo-500/10',
      action: () => { openWizard('service'); requestClose(); }
    },
    {
      id: 'digital',
      category: 'sell',
      title: 'Digital Product',
      description: 'Sell courses, e-books, or software',
      icon: Download,
      color: 'text-purple-400',
      bg: 'bg-purple-500/10',
      action: () => { openWizard('digital'); requestClose(); }
    },
    {
      id: 'asset_3d',
      category: 'sell',
      title: '3D Asset',
      description: 'Sell models, textures, rigs, animations or asset packs',
      icon: Box,
      color: 'text-sky-400',
      bg: 'bg-sky-500/10',
      action: () => { openWizard('asset_3d'); requestClose(); }
    },
    {
      id: 'bundle',
      category: 'sell',
      title: 'Bundle',
      description: 'Package multiple products into one offer',
      icon: Layers,
      color: 'text-violet-400',
      bg: 'bg-violet-500/10',
      action: () => { openWizard('bundle'); requestClose(); }
    },
    {
      id: 'virtual',
      category: 'sell',
      title: 'Virtual Item',
      description: 'Sell in-game items, skins, or currency',
      icon: Gamepad2,
      color: 'text-pink-400',
      bg: 'bg-pink-500/10',
      action: () => { openWizard('virtual'); requestClose(); }
    },
    {
      id: 'community',
      category: 'grow',
      title: 'Paid Community',
      description: 'Start a paid community or group',
      icon: Users,
      color: 'text-amber-400',
      bg: 'bg-amber-500/10',
      action: () => { openWizard('community'); requestClose(); }
    },
    {
      id: 'pos',
      category: 'sell',
      title: 'POS Item',
      description: 'Add a product to your POS systems',
      icon: Monitor,
      color: 'text-cyan-400',
      bg: 'bg-cyan-500/10',
      action: () => { openWizard('pos_item'); requestClose(); }
    },
    {
      id: 'affiliate',
      category: 'grow',
      title: 'Affiliate Product',
      description: 'Promote external products via link',
      icon: Link,
      color: 'text-orange-400',
      bg: 'bg-orange-500/10',
      action: () => { openWizard('affiliate'); requestClose(); }
    },
    {
      id: 'announcement',
      category: 'grow',
      title: 'Announcement',
      description: 'Share news or updates with a link',
      icon: Megaphone,
      color: 'text-red-400',
      bg: 'bg-red-500/10',
      action: () => { openWizard('announcement'); requestClose(); }
    }
  ];
  const categories = [
    { id: 'sell' as const, label: 'Sell' },
    { id: 'money' as const, label: 'Get paid' },
    { id: 'grow' as const, label: 'Grow' },
  ];
  const visibleOptions = options.filter((option) => option.category === activeCategory);

  return (
    <AnimatePresence>
      {isVisible && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={requestClose}
            className="fixed inset-0 z-[190] bg-black/45 backdrop-blur-[3px] md:hidden"
          />
          <motion.div
            initial={{ ...dropdownPanelMotion.initial, y: 24 }}
            animate={dropdownPanelMotion.animate}
            exit={{ ...dropdownPanelMotion.exit, y: 18 }}
            transition={dropdownPanelMotion.transition}
            onPointerMove={trackLiquidGlassPointer}
            onPointerLeave={resetLiquidGlassPointer}
            role="dialog"
            aria-modal="true"
            aria-labelledby="workspace-create-title"
            className="wersee-liquid-glass wersee-liquid-glass--thick wersee-dropdown-panel fixed bottom-[calc(76px_+_env(safe-area-inset-bottom))] left-3 right-3 z-[200] flex max-h-[calc(100dvh_-_100px_-_env(safe-area-inset-bottom))] origin-bottom flex-col overflow-hidden rounded-[2rem] md:bottom-auto md:left-auto md:right-8 md:top-20 md:max-h-[calc(100dvh-6rem)] md:w-[440px] md:max-w-[calc(100vw-2rem)] md:origin-top-right"
          >
            <div className="flex w-full shrink-0 justify-center pb-1 pt-3 md:hidden">
              <div className="h-1 w-10 rounded-full bg-white/15" />
            </div>
            
            <div className="flex shrink-0 items-center justify-between px-5 pb-4 pt-3 md:px-6 md:pb-5 md:pt-6">
              <div className="min-w-0 pr-4">
                <h3 id="workspace-create-title" className="text-xl font-semibold tracking-tight text-white md:text-2xl">Create</h3>
                <p className="mt-0.5 text-xs text-white/40">Choose what you want to make.</p>
              </div>
              <div className="flex items-center gap-1">
                <button
                  type="button"
                  onClick={() => { setIsAgentMode(!isAgentMode); requestClose(); if (!isAgentMode) onOpenAi(); }}
                  className={`flex h-9 w-9 items-center justify-center rounded-full transition-colors ${isAgentMode ? 'bg-indigo-500/15 text-indigo-300' : 'text-white/40 hover:bg-white/[0.06] hover:text-white'}`}
                  aria-label={isAgentMode ? 'Disable AI mode' : 'Create with AI'}
                >
                  <Sparkles className="h-4 w-4" aria-hidden="true" />
                </button>
                <button
                  type="button"
                  onClick={requestClose}
                  className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-white/45 transition-colors hover:bg-white/[0.06] hover:text-white active:scale-90"
                  aria-label="Close create menu"
                >
                  <X className="h-4 w-4" aria-hidden="true" />
                </button>
              </div>
            </div>

            {user && (declarationLoading || !declared) ? (
              declarationLoading ? (
                <div className="flex min-h-64 items-center justify-center text-sm font-bold text-gray-500">Checking your seller account…</div>
              ) : (
                <SellerAccountSetup onComplete={markDeclared} />
              )
            ) : <>
              <div className="mx-4 grid shrink-0 grid-cols-3 gap-1 rounded-2xl border border-white/[0.06] bg-black/15 p-1 md:mx-5">
                {categories.map((category) => (
                  <button
                    key={category.id}
                    type="button"
                    onClick={() => setActiveCategory(category.id)}
                    className={`rounded-xl px-3 py-2 text-xs font-medium transition-colors ${
                      activeCategory === category.id
                        ? 'bg-white/[0.1] text-white shadow-sm'
                        : 'text-white/40 hover:text-white/70'
                    }`}
                  >
                    {category.label}
                  </button>
                ))}
              </div>
              <div className="custom-scrollbar overflow-y-auto p-3 md:p-4">
              <div className="grid grid-cols-2 gap-2">
                {visibleOptions.map((option) => (
                  <button
                    key={option.id}
                    onClick={option.action}
                    className="group flex min-h-[72px] w-full items-center gap-3 rounded-2xl border border-white/[0.055] bg-white/[0.025] p-3 text-left transition-all hover:border-white/15 hover:bg-white/[0.06] active:scale-[0.98]"
                  >
                    <div className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${option.bg} ${option.color} transition-transform group-hover:scale-105`}>
                      <option.icon className="h-4 w-4" aria-hidden="true" />
                    </div>
                    <h3 className="min-w-0 text-sm font-medium leading-tight text-white/90">{option.title}</h3>
                  </button>
                ))}
              </div>
            </div>
            </>}
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
};
